#!/usr/bin/env python3
#
# Most of this was generated by Claude from my simpler code
# deploys an exact number of machines, redeploying failed ones elsewhere
#

import argparse
import concurrent.futures
import jinja2
import json
import logging
import os
import random
import re
import shutil
import subprocess
import sys
import threading
import time
import yaml

from base64 import b64encode
from pathlib import Path
from urllib.error import HTTPError
from urllib.request import Request, urlopen, URLError

LOGGER = logging.getLogger("testflinger-submitter")

# Configuration Constants
TESTFLINGER_SERVER = "https://testflinger.canonical.com"
AGENT_DATA_URL = f"{TESTFLINGER_SERVER}/v1/agents/data"
TOKEN_URL = f"{TESTFLINGER_SERVER}/v1/oauth2/token"
OUTPUT_DIR = "output"
DEFAULT_COUNT = 3
MAX_RETRIES = 3  # deployment rounds, and waits for enough free agents per round
RETRY_DELAY = 600  # seconds to wait when not enough agents are available
MAX_FAIL_STREAK = 2  # skip agents that failed to provision more times in a row
TIMEOUT_SECONDS = 3600  # 1 hour timeout for operations


def get_log_formatter():
    return logging.Formatter(
        fmt="%(asctime)s %(name)s %(levelname)s %(message)s",
        datefmt="%Y-%m-%d-%H:%M:%S",
    )


def configure_logging(project_dir="generated/sunbeam", log_level=logging.DEBUG):
    """Configure logging.

    :param str project_dir: Project directory
    :param int log_level: logging level. Defaults to logging.INFO
    :returns: None
    """
    default_logger = logging.getLogger()
    default_logger.setLevel(log_level)
    ch = logging.StreamHandler()
    formatter = get_log_formatter()
    ch.setFormatter(formatter)
    ch.setLevel(log_level)
    default_logger.addHandler(ch)
    if os.path.isdir(project_dir):
        fh = logging.FileHandler(os.path.join(project_dir, "output.log"))
        fh.setFormatter(formatter)
        fh.setLevel(log_level)
        default_logger.addHandler(fh)


def load_dotenv(path=".env"):
    """Populate os.environ from a .env file (KEY=VALUE per line).

    Existing environment variables take precedence and are not overwritten.
    A missing file is silently ignored.
    """
    p = Path(path)
    if not p.exists():
        return
    for raw in p.read_text().splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        if line.startswith("export "):
            line = line[len("export ") :]
        key, sep, value = line.partition("=")
        if not sep:
            continue
        key = key.strip()
        value = value.strip()
        if len(value) >= 2 and value[0] == value[-1] and value[0] in "\"'":
            value = value[1:-1]
        if key and key not in os.environ:
            os.environ[key] = value


class TestflingerError(Exception):
    """Base exception for testflinger-related errors."""

    pass


_tf_token = None
_tf_token_lock = threading.Lock()


def fetch_testflinger_token():
    """Exchange TESTFLINGER_CLIENT_ID/TESTFLINGER_SECRET_KEY for a JWT access
    token via the /v1/oauth2/token endpoint (HTTP Basic auth), mirroring
    testflinger-cli.

    Raises:
        TestflingerError: If credentials are missing or authentication fails
    """
    client_id = os.environ.get("TESTFLINGER_CLIENT_ID")
    secret_key = os.environ.get("TESTFLINGER_SECRET_KEY")
    if not client_id or not secret_key:
        raise TestflingerError(
            "TESTFLINGER_CLIENT_ID and TESTFLINGER_SECRET_KEY must be set"
        )
    encoded = b64encode(f"{client_id}:{secret_key}".encode()).decode("ascii")
    request = Request(
        TOKEN_URL,
        data=b"",
        headers={"Authorization": f"Basic {encoded}"},
        method="POST",
    )
    try:
        with urlopen(request, timeout=30) as response:
            payload = json.loads(response.read().decode())
    except (URLError, json.JSONDecodeError) as e:
        raise TestflingerError(f"Testflinger authentication failed: {e}") from e
    if not isinstance(payload, dict) or "access_token" not in payload:
        raise TestflingerError("Testflinger authentication returned no access token")
    LOGGER.info("Obtained Testflinger access token")
    return payload["access_token"]


def testflinger_token(force_refresh=False):
    """Return the cached Testflinger access token, fetching a new one if
    none is cached yet or force_refresh is set (e.g. after it expired)."""
    global _tf_token
    with _tf_token_lock:
        if force_refresh or _tf_token is None:
            _tf_token = fetch_testflinger_token()
        return _tf_token


class JobAlreadyCancelledError(TestflingerError):
    """Exception raised when attempting to cancel an already cancelled job."""

    pass


class TestflingerSubmitter:
    """Main class to handle testflinger job submission and monitoring."""

    def __init__(self, server_file, count=DEFAULT_COUNT):
        """
        Initialize the TestflingerSubmitter.

        Args:
            server_file (str): Path to file containing server names
            count (int): Exact number of machines to deploy
        """
        self.server_file = server_file
        self.count = count
        self.job_ids = []
        # Agents already used in a previous round, never retried
        self.tried_agents = set()

        self.cancelled_jobs = set()

        # Job state lock to prevent race conditions when updating job states
        self.job_state_lock = threading.Lock()

        # Ensure output directory exists
        Path(OUTPUT_DIR).mkdir(parents=True, exist_ok=True)

    def call_testflinger(self, command):
        """
        Call the testflinger CLI with the given command.

        Args:
            command (list): Command arguments for testflinger-cli

        Returns:
            str: Output from the command

        Raises:
            TestflingerError: If the command fails
            JobAlreadyCancelledError: If attempting to cancel an already cancelled job
        """
        cmd = ["testflinger-cli"]
        cmd.extend(command)
        LOGGER.debug("Executing: %s", " ".join(cmd))

        try:
            return subprocess.check_output(
                cmd, stderr=subprocess.STDOUT, timeout=TIMEOUT_SECONDS
            ).decode()
        except subprocess.CalledProcessError as e:
            output = e.output.decode() if e.output else str(e)
            LOGGER.error("Testflinger command failed: %s", output)

            # Check if this is a cancel command on an already cancelled job
            if (
                command[0] == "cancel"
                and "Invalid job ID specified or the job is already completed/cancelled"
                in output
            ):
                raise JobAlreadyCancelledError(
                    f"Job {command[1]} is already cancelled or completed"
                )

            raise TestflingerError(f"Command failed: {' '.join(cmd)}") from e
        except subprocess.TimeoutExpired:
            LOGGER.error(
                "Testflinger command timed out after %s seconds", TIMEOUT_SECONDS
            )
            raise TestflingerError(f"Command timed out: {' '.join(cmd)}")

    def is_job_running(self, job_id):
        """
        Check if a job is currently running and can be cancelled.

        Args:
            job_id (str): The ID of the job to check

        Returns:
            bool: True if the job is still running, False otherwise
        """
        try:
            output = self.call_testflinger(["status", job_id])
            # If "completed" or "cancelled" appears in the status, the job is no longer running
            if "completed" in output or "cancelled" in output:
                return False
            return True
        except TestflingerError:
            # If we can't get the status, assume it's not running
            return False

    def safe_cancel_job(self, job_id):
        """
        Cancel a job safely, checking if it's already been cancelled first.

        Args:
            job_id (str): The ID of the job to cancel

        Returns:
            bool: True if the job was cancelled, False if it was already cancelled
        """
        with self.job_state_lock:
            # Check if this job has already been cancelled
            if job_id in self.cancelled_jobs:
                LOGGER.debug("Job %s already cancelled, skipping", job_id)
                return False

            # Check if the job is still running
            if not self.is_job_running(job_id):
                LOGGER.debug("Job %s no longer running, marking as cancelled", job_id)
                self.cancelled_jobs.add(job_id)
                return False

            try:
                # Try to cancel the job
                self.call_testflinger(["cancel", job_id])
                LOGGER.info("Successfully cancelled job %s", job_id)
                self.cancelled_jobs.add(job_id)
                return True
            except JobAlreadyCancelledError:
                # Job was already cancelled
                LOGGER.debug("Job %s was already cancelled", job_id)
                self.cancelled_jobs.add(job_id)
                return False
            except TestflingerError as e:
                LOGGER.warning("Error cancelling job %s: %s", job_id, str(e))
                return False

    def get_agent_data(self):
        """
        Retrieve agent data from the Testflinger API.

        Returns:
            list: Agent data from the API

        Raises:
            TestflingerError: If API request fails
        """
        def fetch(token):
            request = Request(
                AGENT_DATA_URL, headers={"Authorization": f"Bearer {token}"}
            )
            with urlopen(request, timeout=30) as response:
                if response.getcode() != 200:
                    LOGGER.error(
                        "Failed to retrieve agent data, status code: %s",
                        response.getcode(),
                    )
                    raise TestflingerError(
                        f"API returned status code {response.getcode()}"
                    )
                return json.loads(response.read().decode())

        try:
            try:
                return fetch(testflinger_token())
            except HTTPError as e:
                if e.code != 401:
                    raise
                LOGGER.info("Agent data returned 401; refreshing Testflinger token")
                return fetch(testflinger_token(force_refresh=True))
        except (URLError, json.JSONDecodeError) as e:
            LOGGER.error("Error retrieving agent data: %s", str(e))
            raise TestflingerError("Failed to retrieve or parse agent data") from e


    def get_available_agents(self, servers):
        """
        Get a list of available agents that match the given servers.

        Only agents in "waiting" state with at most MAX_FAIL_STREAK consecutive
        provisioning failures are returned. Agents with a positive streak are
        shuffled to spread load, followed by the rest sorted by streak.

        Args:
            servers (list): List of server names to match against

        Returns:
            list: Names of available agents sorted by suitability
        """
        try:
            data = self.get_agent_data()
        except TestflingerError as e:
            LOGGER.error("Failed to get agent data: %s", str(e))
            return []

        LOGGER.info("Agents from queue:")
        LOGGER.info("%-20s %-10s %s", "Name", "State", "Streak")
        LOGGER.info("-" * 40)

        agents = []
        for entry in data:
            # Check if this agent is in any of our target servers
            if not any(server in entry.get("queues", []) for server in servers):
                continue

            name = entry["name"]
            state = entry["state"]

            # Get the streak information
            try:
                streak = entry["provision_streak_count"]
                streak_type = entry.get("provision_streak_type")
                if streak_type == "fail":
                    streak = -streak
            except KeyError:
                streak = 0

            LOGGER.info("%-20s %-10s %s", name, state, streak)

            # 1 or 2 failures in a row can still be a hiccup, more is suspicious
            if state == "waiting" and streak >= -MAX_FAIL_STREAK:
                agents.append({"name": name, "streak": streak})

        # Sort and shuffle to optimize agent selection
        agents_sorted_by_streak = sorted(
            agents, key=lambda x: x["streak"], reverse=True
        )
        agents_with_positive_streaks = [
            agent for agent in agents_sorted_by_streak if agent["streak"] > 0
        ]
        agents_with_negative_streaks = [
            agent for agent in agents_sorted_by_streak if agent["streak"] <= 0
        ]

        random.shuffle(agents_with_positive_streaks)
        sorted_agents = agents_with_positive_streaks + agents_with_negative_streaks

        LOGGER.info("Available agents by preference:")
        LOGGER.info("%-20s %s", "Name", "Streak")
        LOGGER.info("-" * 40)
        for agent in sorted_agents:
            LOGGER.info("%-20s %s", agent["name"], agent["streak"])

        return [agent["name"] for agent in sorted_agents]

    def wait_for_agents(self, servers, count):
        """
        Wait until at least `count` suitable, not yet tried agents are available.

        Returns:
            list: Exactly `count` agent names, or an empty list on timeout
        """
        for attempt in range(1, MAX_RETRIES + 1):
            agents = [
                agent
                for agent in self.get_available_agents(servers)
                if agent not in self.tried_agents
            ]
            if len(agents) >= count:
                return agents[:count]
            LOGGER.warning(
                "Need %d agents but only %d are available (attempt %d/%d)",
                count,
                len(agents),
                attempt,
                MAX_RETRIES,
            )
            if attempt < MAX_RETRIES:
                LOGGER.info("Retrying in %d seconds", RETRY_DELAY)
                time.sleep(RETRY_DELAY)
        LOGGER.error("Failed to find %d available agents", count)
        return []

    def render_job(self, agent):
        """
        Render the job definition for the given agent from the template.

        Returns:
            str: Path to the rendered YAML file
        """
        template_vars = {
            "job_name": f"job-{agent}",
            "job_queue": agent,
            "distro_series": "noble",
        }
        env = jinja2.Environment(loader=jinja2.FileSystemLoader("."))
        template = env.get_template("testflinger_template_noble.yaml")
        testflinger_filename = os.path.join(OUTPUT_DIR, f"testflinger-{agent}.yaml")
        with open(testflinger_filename, "w") as out:
            out.write(template.render(**template_vars))
        LOGGER.debug("Generated %s", testflinger_filename)
        return testflinger_filename

    def submit_jobs(self, agents):
        """
        Submit one testflinger job per agent.

        Returns:
            list: List of {"job_id", "agent"} dicts for submitted jobs
        """
        jobs = []
        for agent in agents:
            self.tried_agents.add(agent)
            try:
                job_file = self.render_job(agent)
                output = self.call_testflinger(["submit", job_file])
                job_id = re.sub(".*\n.*job_id: ", "", output).strip()
            except (jinja2.exceptions.TemplateError, OSError, TestflingerError) as e:
                LOGGER.error("Failed to submit job for %s: %s", agent, str(e))
                continue
            LOGGER.info("Submitted job %s for agent %s", job_id, agent)
            jobs.append({"job_id": job_id, "agent": agent})
            self.job_ids.append(job_id)
            # Keep cancel.sh current so jobs can be cleaned up if we get killed
            self.create_cancel_script()
        return jobs

    def monitor_job(self, job):
        """
        Poll a single job until it reaches reserve phase (IP known) or ends.

        Returns:
            dict: {"ip", "job_id", "name"}; "ip" is empty on failure
        """
        job_id = job["job_id"]
        LOGGER.debug("Capturing %s output started", job_id)
        output_file = os.path.join(OUTPUT_DIR, f"testflinger-{job_id}.txt")
        ret_val = {"ip": "", "job_id": job_id, "name": job["agent"]}
        process = None

        try:
            with open(output_file, "w") as file:
                process = subprocess.Popen(
                    ["testflinger-cli", "poll", job_id],
                    stdout=subprocess.PIPE,
                    stderr=subprocess.STDOUT,
                    universal_newlines=True,
                )
                for line in process.stdout:
                    output = line.strip()
                    if not output:
                        continue
                    file.write(output + os.linesep)
                    file.flush()
                    if "You can now connect to ubuntu@" in output:
                        ret_val["ip"] = output.split("@")[-1]
                        LOGGER.info("Job %s has IP %s", job_id, ret_val["ip"])
                        break
        except OSError as e:
            LOGGER.error("Error monitoring %s: %s", job_id, str(e))
        finally:
            if process and process.poll() is None:
                try:
                    process.kill()
                except OSError:
                    pass

        LOGGER.debug("Capturing %s output finished: %s", job_id, ret_val)
        return ret_val

    def monitor_jobs(self, jobs):
        """
        Monitor jobs concurrently until each one is reserved or has ended.

        Returns:
            list: Result dicts as returned by monitor_job
        """
        if not jobs:
            return []
        with concurrent.futures.ThreadPoolExecutor(max_workers=len(jobs)) as executor:
            return list(executor.map(self.monitor_job, jobs))

    def read_servers_file(self):
        """
        Read the servers file and return list of servers.

        Returns:
            list: List of server names

        Raises:
            TestflingerError: If file cannot be read
        """
        try:
            with open(self.server_file, "r") as f:
                return f.read().split()
        except OSError as e:
            LOGGER.error("Error reading servers file: %s", str(e))
            raise TestflingerError(
                f"Could not read servers file: {self.server_file}"
            ) from e

    def create_cancel_script(self):
        """Create a shell script to cancel all jobs if needed."""
        try:
            with open("cancel.sh", "w") as f:
                f.write("#!/bin/bash\n\n")
                f.write("# Auto-generated script to cancel testflinger jobs\n\n")
                # testflinger-cli needs TESTFLINGER_CLIENT_ID/SECRET_KEY
                f.write(
                    'ENV_FILE="$(dirname "$0")/.env"\n'
                    'if [ -f "$ENV_FILE" ]; then set -a; . "$ENV_FILE"; set +a; fi\n\n'
                )
                for job_id in self.job_ids:
                    f.write(f"testflinger-cli cancel {job_id}\n")
            os.chmod("cancel.sh", 0o755)
        except OSError as e:
            LOGGER.warning("Could not create cancel script: %s", str(e))

    def is_reserved(self, job_id):
        """Return True if the job is currently in the reserve phase."""
        try:
            return "reserve" in self.call_testflinger(["status", job_id])
        except TestflingerError as e:
            LOGGER.warning("Error verifying job %s: %s", job_id, str(e))
            return False

    def run(self):
        """
        Deploy exactly `count` machines, redeploying failed ones on other agents.

        Returns:
            int: 0 for success, 1 for failure
        """
        deployed = []
        try:
            servers = self.read_servers_file()
            LOGGER.info("Looking for agents on servers: %s", ", ".join(servers))
            LOGGER.info("Going to deploy %d machines", self.count)

            for attempt in range(1, MAX_RETRIES + 1):
                needed = self.count - len(deployed)
                LOGGER.info(
                    "Deployment round %d/%d: deploying %d machines",
                    attempt,
                    MAX_RETRIES,
                    needed,
                )
                agents = self.wait_for_agents(servers, needed)
                if not agents:
                    break
                LOGGER.debug("Going to use %s", agents)

                jobs = self.submit_jobs(agents)
                for result in self.monitor_jobs(jobs):
                    if result["ip"] and self.is_reserved(result["job_id"]):
                        deployed.append(result)
                    else:
                        LOGGER.warning(
                            "%s with %s failed: %s/jobs/%s",
                            result["name"],
                            result["job_id"],
                            TESTFLINGER_SERVER,
                            result["job_id"],
                        )
                        self.safe_cancel_job(result["job_id"])

                LOGGER.info("Deployed %d/%d machines", len(deployed), self.count)
                if len(deployed) >= self.count:
                    break

            if len(deployed) < self.count:
                LOGGER.error(
                    "Failed to deploy %d machines, only %d were deployed",
                    self.count,
                    len(deployed),
                )
                for result in deployed:
                    self.safe_cancel_job(result["job_id"])
                return 1

            LOGGER.info("Successfully deployed %d machines", len(deployed))
            print(yaml.dump(deployed, sort_keys=False))
            print(" ".join(result["ip"] for result in deployed))
            return 0

        except TestflingerError as e:
            LOGGER.error("Fatal error: %s", str(e))
            return 1
        except Exception as e:
            LOGGER.exception("Unexpected error: %s", str(e))
            return 1


def parse_arguments():
    """
    Parse command line arguments.

    Returns:
        argparse.Namespace: Parsed arguments
    """
    parser = argparse.ArgumentParser(description="Submit and monitor testflinger jobs")
    parser.add_argument("server_file", help="File containing server names")
    parser.add_argument(
        "--count",
        type=int,
        default=DEFAULT_COUNT,
        help=f"Exact number of machines to deploy (default: {DEFAULT_COUNT})",
    )
    parser.add_argument("--debug", action="store_true", help="Enable debug logging")

    return parser.parse_args()


if __name__ == "__main__":
    args = parse_arguments()
    load_dotenv()
    configure_logging()

    if args.count < 1:
        LOGGER.error("--count must be at least 1")
        sys.exit(2)

    if not shutil.which("testflinger-cli"):
        LOGGER.error(
            "testflinger-cli not found in PATH (install: sudo snap install testflinger-cli)"
        )
        sys.exit(2)

    # testflinger-cli subprocesses inherit these from os.environ
    try:
        testflinger_token()
    except TestflingerError as e:
        LOGGER.error("%s", e)
        sys.exit(2)

    submitter = TestflingerSubmitter(args.server_file, count=args.count)

    exit_code = submitter.run()
    sys.exit(exit_code)
